<?php
namespace App\Http\Controllers\Api;
use Illuminate\Routing\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,Cache,Mail,Storage};
use Illuminate\Support\Str;
use App\Services\{Commerce,Catalog,Support,Registration};

class MobileBuyerController extends Controller
{
 public static function productCard($p){$p->effective_price=Catalog::price($p);$images=json_decode($p->images??'[]',true)?:[];$p->image_urls=array_values(array_filter(array_map(fn($x)=>Support::imageUrl($x),$images)));return $p;}
 public function categories(){return response()->json(['main_categories'=>config('registration.categories'),'subcategories'=>DB::table('categories')->whereNotNull('category_code')->orderBy('id')->get()]);}
 public function quote(Request $r){return response()->json(Commerce::checkout($r,true));}
 public function wishlist(){return response()->json(Commerce::catalog(DB::table('products'))->join('wishlists as w','w.product_id','=','products.id')->where('w.buyer_id',auth()->id())->select('products.*')->get()->map(fn($p)=>self::productCard($p)));}
 public function stores(){return response()->json(DB::table('seller_businesses as s')->join('store_follows as f','f.seller_id','=','s.user_id')->where('f.buyer_id',auth()->id())->select('s.*')->get());}
 public function store(Request $r,int $id){$seller=DB::table('users')->where('id',$id)->where('role','seller')->where('active',1)->where('approval_status','approved')->where('account_status','active')->first();abort_unless($seller,404);$store=DB::table('seller_businesses')->where('user_id',$id)->first();abort_unless($store,404);$store->logo_url=Support::imageUrl($store->logo??null);return response()->json(['store'=>$store,'following'=>auth()->check()&&DB::table('store_follows')->where('buyer_id',auth()->id())->where('seller_id',$id)->exists(),'categories'=>DB::table('store_categories')->where('seller_id',$id)->where('visible',1)->get(),'products'=>Catalog::query(new Request(['seller'=>$id]+$r->only(['store_category','q','sort'])))->paginate(20)->through(fn($p)=>self::productCard($p))]);}
 public function vouchers(){return response()->json(DB::table('vouchers')->where('active',1)->where(fn($q)=>$q->whereNull('starts_at')->orWhere('starts_at','<=',now()))->where(fn($q)=>$q->whereNull('expires_at')->orWhere('expires_at','>',now()))->get()->map(function($v){$v->claimed=DB::table('voucher_claims')->where('buyer_id',auth()->id())->where('voucher_id',$v->id)->exists();return $v;}));}
 public function reviews(){return response()->json(['reviews'=>DB::table('item_reviews as r')->join('order_items as i','i.id','=','r.order_item_id')->where('r.buyer_id',auth()->id())->select('r.*','i.name as product_name')->orderByDesc('r.id')->get()->map(function($r){$r->photo_urls=array_map(fn($p)=>Support::imageUrl($p),json_decode($r->photos??'[]',true)?:[]);return $r;}),'eligible_items'=>DB::table('order_items as i')->join('orders as o','o.id','=','i.order_id')->where('o.buyer_id',auth()->id())->where('o.status','COMPLETED')->where('o.completed_at','>=',now()->subDays(30))->select('i.*')->get()]);}
 public function returns(){return response()->json(DB::table('return_requests')->where('buyer_id',auth()->id())->orderByDesc('id')->get()->map(function($r){$r->photo_urls=array_map(fn($i)=>url('/api/returns/'.$r->id.'/photos/'.$i),array_keys(json_decode($r->photos??'[]',true)?:[]));unset($r->photos);return $r;}));}
 public function returnPhoto(int $id,int $index){$r=DB::table('return_requests')->where('id',$id)->where('buyer_id',auth()->id())->first();abort_unless($r,404);$photos=json_decode($r->photos,true);abort_unless(isset($photos[$index]),404);$disk=Storage::disk('local');abort_unless($disk->exists($photos[$index]),404);return response()->file($disk->path($photos[$index]),['Cache-Control'=>'private, no-store']);}
 public function attachment(int $id){$m=DB::table('messages')->where('id',$id)->where(fn($q)=>$q->where('sender_id',auth()->id())->orWhere('recipient_id',auth()->id()))->first();abort_unless($m&&$m->attachment,404);$disk=Storage::disk('local');abort_unless($disk->exists($m->attachment),404);return response()->file($disk->path($m->attachment),['Cache-Control'=>'private, no-store']);}
 public function password(Request $r){$v=$r->validate(['current_password'=>'required','password'=>['required','confirmed',\Illuminate\Validation\Rules\Password::min(8)->mixedCase()->numbers()->symbols()]]);if(!Hash::check($v['current_password'],auth()->user()->password))Support::fail('current_password','Current password is incorrect.');DB::table('users')->where('id',auth()->id())->update(['password'=>Hash::make($v['password']),'remember_token'=>null,'api_token_expires_at'=>null,'updated_at'=>now()]);return response()->json(['message'=>'Password updated. Sign in again.','reauthenticate'=>true]);}
 public function contactRequest(Request $r){$v=$r->validate(['password'=>'required','email'=>'nullable|email','phone'=>'nullable|string']);if(!Hash::check($v['password'],auth()->user()->password))Support::fail('password','Password is incorrect.');$data=[];if(!empty($v['email']))$data['email']=mb_strtolower(trim($v['email']));if(!empty($v['phone'])){$data['phone']=Registration::normalizePhone($v['phone']);if(!preg_match('/^09[0-9]{9}$/',$data['phone']))Support::fail('phone','Enter a Philippine mobile number.');$data['phone_normalized']=$data['phone'];}if(!$data)Support::fail('contact','Enter a new email or phone.');$this->uniqueContacts($data);$id=Str::random(40);$otp=(string)random_int(100000,999999);Cache::put('buyer-contact:'.auth()->id().':'.$id,['data'=>$data,'hash'=>Hash::make($otp),'attempts'=>0,'expires'=>now()->addMinutes(5)->timestamp],now()->addMinutes(5));Mail::raw('Your account change verification code is '.$otp,fn($m)=>$m->to($data['email']??auth()->user()->email)->subject('Verify account change'));return response()->json(['message'=>'Verification code sent by email.','challenge'=>$id]);}
 private function uniqueContacts(array $data):void{foreach(['email','phone'] as $field)if(isset($data[$field])&&DB::table('users')->where(fn($q)=>$field==='phone'?$q->where('phone',$data[$field])->orWhere('phone_normalized',$data[$field]):$q->where($field,$data[$field]))->where('id','!=',auth()->id())->exists())Support::fail($field,ucfirst($field).' already used.');}
 public function contactVerify(Request $r){$v=$r->validate(['challenge'=>'required|string|size:40','otp'=>['required','regex:/^[0-9]{6}$/']]);$key='buyer-contact:'.auth()->id().':'.$v['challenge'];return Cache::lock($key.':lock',10)->block(5,function()use($key,$v){$x=Cache::get($key);if(!$x||$x['attempts']>=5||($x['expires']??0)<=now()->timestamp)Support::fail('otp','Expired or locked verification request.');if(!Hash::check($v['otp'],$x['hash'])){$x['attempts']++;Cache::put($key,$x,max(1,$x['expires']-now()->timestamp));Support::fail('otp','Incorrect verification code.');}$this->uniqueContacts($x['data']);DB::table('users')->where('id',auth()->id())->update($x['data']+['remember_token'=>null,'api_token_expires_at'=>null,'updated_at'=>now()]);Cache::forget($key);return response()->json(['message'=>'Contact updated. Sign in again.','reauthenticate'=>true]);});}
}
